const items = $input.all();
const question = $('User Question').first().json.chatInput || '';

const blocks = [];
const sources = [];

for (const it of items) {
  const j = it.json || {};
  const doc = j.document || j;
  const content = doc.pageContent || doc.content || '';
  const meta = doc.metadata || j.metadata || {};
  if (!content) continue;

  const topic = meta.topic || meta.source || '';
  const id = meta.id || '';
  const label = [topic, id ? '(id: ' + id + ')' : ''].filter(Boolean).join(' ');

  blocks.push('[Source: ' + (label || 'unknown') + ']\n' + content);
  if (label) sources.push(label);
}

const uniqueSources = [...new Set(sources)];
const context = blocks.join('\n\n---\n\n');

return [{
  json: {
    question,
    context: context || 'NO_CONTEXT_FOUND',
    sources: uniqueSources,
    sourcesText: uniqueSources.length ? uniqueSources.join('; ') : '',
  },
}];

const fallback = 'Information not available in the knowledge base.';
const raw = ($json.text || $json.output || $json.response || '').toString().trim();
const sourcesText = $('Build Context & Sources').item.json.sourcesText || '';

const isFallback =
  raw.toLowerCase().includes('information not available in the knowledge base');

let output;
if (!raw || isFallback) {
  // Safe fallback: never answer from general knowledge, never show sources
  output = fallback;
} else {
  const hasSourceLine = /source\s*:/i.test(raw);
  output = hasSourceLine || !sourcesText
    ? raw
    : raw + '\n\nSource: ' + sourcesText;
}

return { json: { output, answer: output, sources: sourcesText, grounded: !isFallback && !!raw } };
